    "title": "모델",
    "welcomeBody": "DeepSeek Harness 0.2는 아직 프리뷰 단계라 여러 부분을 계속 다듬고 개선해야 합니다. 모든 개발자와 사용자의 피드백과 제안을 환영합니다. 새 데스크톱 앱은 이제 폭넓은 사용자를 대상으로 합니다. 개발자용 고급 기능은 설정에서 켤 수 있습니다. DeepSeek Harness의 제품 기능과 플러그인 API는 앞으로도 빠르게 바뀌다가 차차 안정될 예정입니다.\n\n오픈 소스로 재사용하고 조합할 수 있는 기반 위에서, 전 세계 사용자와 개발자와 함께 지능의 한계를 탐구해 나가고 싶습니다. 누구든 DeepSeek Harness로 아이디어를 실현하고 커뮤니티에 참여해 플러그인 생태계를 함께 넓혀 주시길 바랍니다.",
