    "DeepSeek Harness 通过 macOS Messages.app 收发文本消息。首次使用需要授予以下权限：": "DeepSeek Harness는 macOS Messages.app으로 메시지를 주고받습니다. 처음 사용할 때 다음 권한이 필요합니다:",
