    "Harness 健康检查超时。请确认 dsh web 未阻塞。": "Harness 상태 확인 시간이 초과되었습니다. 호스트가 응답하는지 확인해 주세요.",
    "Harness 健康检查返回服务错误。请查看 DSH 日志。": "Harness 상태 확인에서 서비스 오류가 반환되었습니다. DSH 로그를 확인해 주세요.",
    "Harness 健康检查需要身份认证。请检查代理、网关或自定义鉴权配置。": "Harness 상태 확인에 인증이 필요합니다. 프록시, 게이트웨이 또는 사용자 지정 인증 설정을 확인해 주세요.",
    "Harness 异常拒绝了回环地址的健康检查。请检查 HTTP 代理、Harness 源码版本和构建产物。": "Harness가 루프백 주소의 상태 확인을 거부했습니다. HTTP 프록시와 실행 중인 Harness 빌드를 확인해 주세요.",
    "Harness 拒绝了健康检查请求。请查看 DSH 日志。": "Harness가 상태 확인 요청을 거부했습니다. DSH 로그를 확인해 주세요.",
    "Harness 的 Host 信任检查拒绝了非回环地址请求。请检查 harnessBaseUrl 与 trustedHosts 配置。": "Harness가 루프백이 아닌 호스트를 거부했습니다. harnessBaseUrl과 trustedHosts 설정을 확인해 주세요.",
    "Harness 返回了无法识别的响应。请确认 Harness 与插件版本兼容。": "Harness가 알 수 없는 응답을 반환했습니다. Harness와 플러그인 버전이 호환되는지 확인해 주세요.",
