    "上次安装结果无法确认，请先检查此 profile 的插件安装状态。": "이전 설치 결과를 확인할 수 없습니다. 먼저 이 프로필의 플러그인 설치 상태를 확인해 주세요.",
    "上次更新已中断，请检查安装状态后重试。": "이전 업데이트가 중단되었습니다. 설치 상태를 확인한 뒤 다시 시도해 주세요.",
