    "上移": "위로 이동",
    "下移": "아래로 이동",
    "不可以执行命令": "명령 실행 불가",
    "不是邮箱登录密码；请在邮箱设置中单独生成。": "메일 로그인 비밀번호가 아닙니다. 메일함 설정에서 따로 생성해 주세요.",
    "不显示过程（只发送最终答案）": "과정 숨기기(최종 답변만 보내기)",
    "不绑定则每封新邮件开启一个新会话；绑定固定会话后，来信都在该会话内继续。": "연결하지 않으면 새 메일마다 새 세션이 시작됩니다. 고정 세션을 연결하면 받은 메일이 모두 그 세션에서 이어집니다.",
    "不绑定（每封新邮件新建会话）": "연결 안 함(메일마다 새 세션)",
    "个失败。": "개 실패.",
    "个机器人。": "개 봇.",
