    "个飞书机器人，它们各自的面板设置会被覆盖。": "개에 씁니다. 각 봇의 기존 패널 설정은 덮어씁니다.",
    "主目录": "홈",
    "二维码图片未就绪，请使用备用链接。": "QR 코드가 준비되지 않았습니다. 대체 링크를 사용해 주세요.",
    "二维码图片未就绪，请重新生成。": "QR 코드가 준비되지 않았습니다. 새로 생성해 주세요.",
    "二维码图片正在生成…": "QR 코드 생성 중…",
    "二维码已失效": "QR 코드 만료됨",
    "二维码已过期": "QR 코드 만료됨",
    "二维码已过期\n请重新生成": "QR 코드 만료됨\n새로 생성해 주세요",
    "二维码已过期\\n请重新生成": "QR 코드 만료됨\\n새로 생성해 주세요",
    "二维码有效时间": "QR 코드 남은 시간",
    "二维码未就绪，请打开授权链接": "QR 코드가 준비되지 않았습니다. 승인 링크를 열어 주세요.",
    "二维码正在生成…": "QR 코드 생성 중…",
    "二维码正在自动刷新…": "QR 코드 새로 고치는 중…",
    "二维码由腾讯微信 iLink 服务签发。用手机微信扫描并确认后，账号凭据会直接写入 Harness Host，浏览器不会收到 bot_token。": "QR 코드는 Tencent WeChat iLink에서 발급합니다. 스캔하고 확인하면 계정 자격 증명이 Harness 호스트에 바로 저장되며 브라우저에는 노출되지 않습니다.",
    "仅依据当前消息的 <dsh_im_source> 中实际提供的字段理解来源；没有提供的字段不要猜测或补全。\nconversationType是群聊时回复严肃一点，conversationType是私聊时回复一定要幽默搞笑，像周星驰的电影一样搞笑": "현재 메시지의 <dsh_im_source>에 실제로 있는 필드만으로 출처를 이해하세요. 없는 필드는 추측하거나 채우지 마세요.\nconversationType이 그룹이면 더 진지하게 답하고, 개인 채팅이면 유머러스하고 재미있게 답하세요.",
    "仅依据当前消息的 <dsh_im_source> 中实际提供的字段理解来源；没有提供的字段不要猜测或补全。\n当前消息来自私聊，可以使用更轻松、幽默、详细的表达方式。": "현재 메시지의 <dsh_im_source>에 실제로 있는 필드만으로 출처를 이해하세요. 없는 필드는 추측하거나 채우지 마세요.\n이 메시지는 개인 채팅에서 왔습니다. 더 가볍고 유머러스하며 자세하게 답해도 됩니다.",
    "仅依据当前消息的 <dsh_im_source> 中实际提供的字段理解来源；没有提供的字段不要猜测或补全。\n当前消息来自群聊，请使用严肃、克制、简洁的表达方式。": "현재 메시지의 <dsh_im_source>에 실제로 있는 필드만으로 출처를 이해하세요. 없는 필드는 추측하거나 채우지 마세요.\n이 메시지는 그룹 채팅에서 왔습니다. 진지하고 절제된 말투로 간결하게 답하세요.",
    "仅在 @机器人时响应（推荐）": "@멘션될 때만 응답(권장)",
    "仅在私聊开关开启时使用。清空并保存后不再附加私聊增强提示词；所选来源字段仍按当前场景设置发送。": "개인 채팅 보강을 켰을 때만 사용합니다. 비우고 저장하면 개인 채팅 안내를 붙이지 않습니다. 선택한 출처 필드는 계속 개인 채팅 설정을 따릅니다.",
    "仅在群聊开关开启时使用。清空并保存后不再附加群聊增强提示词；所选来源字段仍按当前场景设置发送。": "그룹 채팅 보강을 켰을 때만 사용합니다. 비우고 저장하면 그룹 채팅 안내를 붙이지 않습니다. 선택한 출처 필드는 계속 그룹 채팅 설정을 따릅니다.",
    "仅指定联系人模式使用白名单，切换模式时会保留。": "허용 목록은 지정한 연락처만 모드에서 사용하며, 모드를 바꿔도 유지됩니다.",
