    "加载渠道配置": "채널 구성 불러오기",
    "升级到 dsh-im 4.26.0 前，请先将 DSH 升级到 v0.1.7-alpha.1；使用旧版 DSH 请保留 dsh-im 4.25.0。": "dsh-im 4.26.0으로 업데이트하기 전에 DSH를 v0.1.7-alpha.1로 업그레이드해 주세요. 이전 DSH 버전을 쓴다면 dsh-im 4.25.0을 유지해 주세요.",
    "协议 Hook 预览": "프로토콜 Hook 미리보기",
    "单聊": "개인 채팅",
    "原名称": "원래 이름",
    "原因链已截断": "원인 체인이 잘림",
    "原图接收上限 (MB)": "원본 이미지 수신 한도(MB)",
    "原所有者或扫码接入者始终可以访问并执行命令；以下设置仅约束其他用户。": "원래 소유자나 QR 코드를 스캔한 사람은 언제나 봇에 접근하고 명령을 실행할 수 있습니다. 아래 설정은 다른 사용자에게만 적용됩니다.",
    "原账号状态尚未确认，请重新读取状态，并反馈诊断信息。": "이전 계정 상태가 확인되지 않았습니다. 상태를 새로 고치고 진단 정보를 공유해 주세요.",
