    "发送者标识可能包含平台用户 ID 或电话号码形式的标识。关闭开关不会删除已经写入会话历史的信息。": "보낸 사람 ID에는 플랫폼 사용자 ID나 전화번호 형태의 식별자가 들어 있을 수 있습니다. 이 옵션을 꺼도 대화 기록에 이미 저장된 정보는 지워지지 않습니다.",
    "取消": "취소",
    "取消授权": "승인 취소",
