    "取消补全": "설정 취소",
    "只响应已绑定 WhatsApp 账号的自聊消息。": "연결된 WhatsApp 계정의 나와의 채팅 메시지에만 응답합니다.",
    "只影响新建会话；若当前聊天已有会话，先发送 /new，再发送普通消息生效。": "새 세션에만 적용됩니다. 현재 채팅에 이미 세션이 있다면 /new를 보낸 다음 일반 메시지를 보내야 적용됩니다.",
    "只需填写正文，插件自动添加 <dsh_im_source_guidance> 成对标签。清空并保存后，不再附加增强提示词，已选来源字段仍按开关设置发送。": "본문만 입력하세요. 플러그인이 <dsh_im_source_guidance> 태그 쌍을 붙입니다. 비우고 저장하면 안내를 붙이지 않습니다. 선택한 출처 필드는 계속 대화 스위치 설정을 따릅니다.",
    "可以包含开头的 +，保存时会自动移除。": "맨 앞의 +는 입력해도 되며 저장할 때 제거됩니다.",
    "可以执行命令": "명령 실행 가능",
    "合成模型(TTS)": "음성 합성 모델(TTS)",
