    "命令权限必须是布尔值。": "명령 권한은 boolean 값이어야 합니다.",
    "响应所有私聊、已绑定账号自己发出的群聊消息，以及其他群成员的提及或回复。": "모든 개인 채팅, 연결된 계정이 보낸 그룹 메시지, 다른 그룹 구성원의 멘션이나 답장에 응답합니다.",
    "响应所有群消息": "모든 그룹 메시지에 응답",
    "响应所有群消息（需飞书敏感权限）": "모든 그룹 메시지에 응답(Feishu 민감 권한 범위 필요)",
    "响应自聊和白名单联系人的私聊，忽略群聊。": "나와의 채팅과 허용 목록에 있는 개인 채팅에 응답하고, 그룹 메시지는 무시합니다.",
    "回复音色": "답장 음성",
    "回调 Token": "Callback Token",
    "回调 URL（填入企业微信后台「接收消息 → 设置API接收」）": "콜백 URL(WeCom 관리 콘솔의 메시지 수신 → API 수신에 붙여 넣기)",
    "回调密钥已重置，请把新的回调 URL 更新到企业微信后台。": "콜백 비밀 키를 재설정했습니다. WeCom 관리 콘솔에서 새 콜백 URL로 바꿔 주세요.",
    "回调密钥重置失败，请稍后重试。": "콜백 비밀 키를 재설정하지 못했습니다. 잠시 후 다시 시도해 주세요.",
    "固定会话（账号级）": "고정 세션(계정 단위)",
    "图片 {index}（原图文件：{name}）": "이미지 {index}(원본 파일: {name})",
    "图片下载地址发生了重定向，暂时无法读取。": "이미지 다운로드가 리디렉션되어 읽을 수 없습니다.",
    "图片下载失败，请重新发送后再试。": "이미지를 다운로드하지 못했습니다. 다시 보내 주세요.",
    "图片内容无效或格式不受支持，请重新发送。": "이미지가 올바르지 않거나 지원하지 않는 형식입니다. 다시 보내 주세요.",
    "图片分辨率过高，请压缩后重试。": "이미지 해상도가 너무 높습니다. 압축한 뒤 다시 시도해 주세요.",
    "图片原文件已保存到工作区，文件清单中的图片序号与本条消息一致。图片内容块可能经过缩放或压缩；需要查看细节时可用工具读取原文件。": "원본 이미지는 워크스페이스에 저장됩니다. 파일 목록의 이미지 번호는 이 메시지의 번호와 같습니다. 이미지 블록은 크기가 조정되거나 압축될 수 있으니 세부 내용은 도구로 원본을 읽어 확인하세요.",
    "图片总大小超过宿主限制，请减少图片或压缩后重试。": "이미지가 호스트의 전체 크기 한도를 넘었습니다. 일부 이미지를 빼거나 압축한 뒤 다시 시도해 주세요.",
    "图片格式与实际内容不一致，请重新发送。": "선언된 이미지 형식이 실제 내용과 다릅니다. 다시 보내 주세요.",
    "图片超过 5 MB，请压缩后重试。": "이미지가 5MB를 넘습니다. 압축한 뒤 다시 시도해 주세요.",
    "图片超过原图接收上限 {maxMb} MB，请压缩后重试，或在通用设置的附件中调整上限。": "이미지가 원본 이미지 수신 한도({maxMb}MB)를 넘습니다. 압축한 뒤 다시 시도하거나 일반 설정 > 첨부 파일에서 한도를 조정해 주세요.",
    "图片超过宿主允许的大小，请压缩后重试。": "이미지가 호스트 크기 한도를 넘었습니다. 압축한 뒤 다시 시도해 주세요.",
    "图片输入": "이미지 입력",
    "图片限制无效：请输入正整数，原图接收上限和总量上限不能小于单图上限。": "이미지 한도가 올바르지 않습니다. 양의 정수를 입력해 주세요. 수신 한도와 전체 한도는 이미지당 한도 이상이어야 합니다.",
    "在 163 邮箱「设置 → POP3/SMTP/IMAP」中开启服务，并新增授权密码。": "163 Mail에서 설정 → POP3/SMTP/IMAP을 열고 서비스를 켠 다음 인증 비밀번호를 추가해 주세요.",
    "在 QQ 邮箱「设置 → 账户」中开启 IMAP/SMTP 服务，并生成 16 位授权码（不是登录密码）。": "QQ Mail에서 설정 → 계정을 열고 IMAP/SMTP를 켠 다음 16자리 인증 코드를 생성해 주세요(로그인 비밀번호 아님).",
    "在“系统设置 → 隐私与安全性 → 完全磁盘访问权限”中，打开运行 DeepSeek Harness 的终端或应用。": "시스템 설정 → 개인정보 보호 및 보안 → 전체 디스크 접근 권한에서 DeepSeek Harness를 실행하는 터미널이나 앱을 켜 주세요.",
    "在“系统设置 → 隐私与安全性 → 自动化”中，允许运行 DeepSeek Harness 的应用控制 Messages。": "시스템 설정 → 개인정보 보호 및 보안 → 자동화에서 DeepSeek Harness를 실행하는 앱이 Messages를 제어하도록 허용해 주세요.",
    "在企业微信中创建自建应用，即可在微信里使用": "WeCom에서 자체 개발 앱을 만들어 WeChat 안에서 사용",
    "在应用管理后台创建自建应用，开启「接收消息」并填入下面的参数。成员的微信关注该企业的微信插件后，就能在微信中与本应用双向对话。": "WeCom 관리 콘솔에서 자체 개발 앱을 만들고 메시지 수신을 켠 다음 아래 값을 입력하세요. 구성원이 WeCom 플러그인을 팔로우하면 WeChat 안에서 이 앱과 바로 대화할 수 있습니다.",
    "在微信中确认连接该机器人": "WeChat에서 봇 연결 확인",
    "在授权页点击“一键创建新机器人”": "승인 페이지에서 “새 봇 만들기” 선택",
    "在线": "온라인",
    "在腾讯授权页面确认创建或绑定机器人": "Tencent 승인 페이지에서 봇 생성 또는 연결 확인",
    "在腾讯授权页面确认创建智能机器人": "Tencent 승인 페이지에서 봇 생성 확인",
    "在飞书中打开": "Feishu에서 열기",
    "填入示例": "예시 사용",
    "填写 @BotFather 生成的 Bot Token": "@BotFather에서 받은 Bot Token 입력",
    "填写 Bot Token": "Bot Token 입력",
    "填写 Discord Developer Portal 的 Bot Token": "Discord Developer Portal에서 받은 Bot Token 입력",
    "填写 Lark 开放平台 App ID": "Lark Developer App ID 입력",
