    "填写 QQ 开放平台 AppID": "QQ Open Platform AppID 입력",
    "填写 QQ 开放平台 AppSecret": "QQ Open Platform AppSecret 입력",
    "填写 group_openid": "group_openid 입력",
    "填写 homeserver 地址与访问令牌，或者用户 ID 与密码，即可让机器人以 CS API 长轮询接收消息并以富文本回复。": "homeserver URL과 액세스 토큰, 또는 사용자 ID와 비밀번호를 입력하세요. 봇은 CS API 롱 폴링으로 메시지를 받고 서식 있는 텍스트로 답장합니다.",
    "填写 homeserver 地址，并提供访问令牌，或者用户 ID 与密码的组合。机器人只访问该 homeserver，不连接第三方服务器。": "homeserver URL과 액세스 토큰, 또는 사용자 ID와 비밀번호를 입력하세요. 봇은 해당 homeserver와만 통신하며 외부 서버와는 통신하지 않습니다.",
    "填写 member_openid": "member_openid 입력",
    "填写 senderStaffId 或 senderId": "senderStaffId 또는 senderId 입력",
    "填写 user_openid": "user_openid 입력",
    "填写 userid": "userid 입력",
    "填写企业微信智能机器人 Bot ID": "WeCom AI 봇 Bot ID 입력",
    "填写企业微信智能机器人 Secret": "WeCom AI 봇 Secret 입력",
    "填写企业微信用户 ID": "WeCom 사용자 ID 입력",
    "填写使用者的 Open ID（ou_xxx），不是机器人 ID": "봇 ID가 아닌 사용자 Open ID(ou_xxx) 입력",
    "填写可发消息的 Channel ID": "봇이 메시지를 보낼 수 있는 Channel ID 입력",
    "填写应用参数": "앱 매개변수 입력",
    "填写微信用户 ID": "WeChat 사용자 ID 입력",
    "填写接收消息的用户 ID": "받는 사람 사용자 ID 입력",
    "填写数字 User ID": "숫자 사용자 ID 입력",
    "填写群 chatid": "그룹 chatid 입력",
    "填写钉钉应用 Client ID": "DingTalk Client ID 입력",
    "填写钉钉应用 Client Secret": "DingTalk Client Secret 입력",
    "填写钉钉用户 ID": "DingTalk 사용자 ID 입력",
    "填写飞书开放平台 App ID": "Feishu Open Platform App ID 입력",
    "填写飞书开放平台 App Secret": "Feishu Open Platform App Secret 입력",
    "增强提示词": "안내 프롬프트",
    "增强提示词中请使用字段名（如 senderId、conversationType）引用这些信息。只发送勾选且当前消息中可用的字段，不会额外查询或补全。": "안내 프롬프트에서는 필드 이름(senderId, conversationType 등)으로 이 값을 참조하세요. 현재 메시지에 있는 선택한 필드만 보내며 추가 조회는 하지 않습니다.",
    "增强提示词中请使用字段名（如 senderId、conversationType）引用这些信息。只发送当前会话中勾选且可用的字段，不会额外查询或补全。": "안내 프롬프트에서는 필드 이름(senderId, conversationType 등)으로 이 값을 참조하세요. 현재 대화에서 선택했고 값이 있는 필드만 보내며 추가 조회는 하지 않습니다.",
    "增量添加当前缺少的卡片回调 card.action.trigger、读取消息内图片或文件所需的 im:message:readonly（飞书显示为“获取单聊、群组消息”）、上传机器人图片或文件所需的 im:resource，以及原生命令面板所需的 application:app_slash_command:read / write；确认页只显示当前缺少项，不会创建新应用。": "빠진 카드 콜백 card.action.trigger, 메시지 속 이미지나 파일을 읽는 im:message:readonly(Feishu에서는 “개인 및 그룹 메시지 읽기”로 표시), 봇이 보내는 이미지나 파일을 업로드하는 im:resource, 기본 명령 패널용 application:app_slash_command:read / write 권한을 추가합니다. 확인 페이지에는 빠진 항목만 표시되며 새 앱은 만들지 않습니다.",
    "复制": "복사",
    "复制 Manifest": "Manifest 복사",
    "复制中…": "복사 중…",
    "复制命令": "명령 복사",
    "复制失败。": "복사하지 못했습니다.",
    "复制失败，请选中命令后按 Ctrl+C 或 ⌘C 复制。": "복사하지 못했습니다. 명령을 선택하고 Ctrl+C 또는 ⌘C를 눌러 복사해 주세요.",
    "复制诊断信息": "진단 정보 복사",
    "复制调用参数": "호출 매개변수 복사",
    "复制配置后，在 Slack 选择 From a manifest；创建完成后生成 connections:write App Token，并将应用安装到工作区。": "Manifest를 복사해 Slack에서 “From a manifest”를 선택하세요. 그런 다음 connections:write App Token을 만들고 앱을 워크스페이스에 설치하세요.",
    "多个原因": "원인 여러 개",
