    "连接检查完成。应用尚未收到可用于测试的私聊消息。": "연결 확인을 마쳤습니다. 앱이 아직 테스트에 쓸 수 있는 개인 채팅을 받지 않았습니다.",
    "连接检查完成。机器人尚未收到可用于测试的私聊消息。": "연결 확인을 마쳤습니다. 봇이 아직 테스트에 쓸 수 있는 개인 채팅을 받지 않았습니다.",
