    "连接检查完成，但测试消息发送失败。": "연결 확인을 마쳤지만 테스트 메시지를 보내지 못했습니다.",
    "连接检查完成，测试消息已发送。": "연결 확인을 마쳤고 테스트 메시지를 보냈습니다.",
