    "适合日常问答：执行过程中不显示工具调用等中间步骤，只回复最终结果": "일상적인 질의응답용: 도구 호출 등 중간 단계는 숨기고 최종 결과만 답장합니다",
    "适用于支持图片的聊天渠道。原图按附件保留时长保存，发送给模型的副本会自动缩放或压缩；无法直接发送时交给模型按文件处理。": "이미지를 지원하는 채팅 채널에 적용됩니다. 원본은 첨부 파일 보관 설정을 따릅니다. 모델에 보내는 사본은 자동으로 크기 조정 또는 압축되며, 직접 보낼 수 없는 이미지는 파일로 제공됩니다.",
    "选择后会自动填写目标信息和调用别名，确认后再保存。": "대화를 선택하면 대상 정보와 호출 별칭이 채워집니다. 저장하기 전에 확인해 주세요.",
