    "需在飞书为该机器人开通“获取群组中所有消息”权限（im:message.group_msg）；开通后，机器人会处理群聊中的所有可见消息。": "이 봇에 Feishu의 “연결된 그룹 채팅의 모든 메시지 읽기” 권한(im:message.group_msg)을 부여합니다. 부여하면 봇이 보이는 모든 그룹 메시지를 처리합니다.",
    "需要 DashScope 密钥(凭据库中以\"凭据引用\"为名的环境变量)与可用 ffmpeg;音色支持 Cherry/Serena/Bella/Chelsie/Momo/Katerina 等 qwen3-tts-flash 官方音色。": "DashScope API 키(위 자격 증명 참조에 지정한 자격 증명 저장소 환경 변수)와 작동하는 ffmpeg가 필요합니다. 지원 음성은 공식 qwen3-tts-flash 음성 Cherry/Serena/Bella/Chelsie/Momo/Katerina입니다.",
    "需要先开启两步验证，再生成「应用专用密码」。": "먼저 2단계 인증을 켠 다음 앱 전용 비밀번호를 생성하세요.",
    "需要处理": "확인 필요",
    "需要配对码": "페어링 코드 필요",
    "面板只决定聊天输入框里打「/」时列出的指令和顺序；被移除的指令仍可手动输入，功能不受影响。同步由机器人后台完成，指令较多时需要一点时间。": "패널은 채팅 입력창의 \"/\" 목록에 어떤 명령을 어떤 순서로 보여 줄지만 정합니다. 목록에서 뺀 명령도 직접 입력하면 계속 작동합니다. 봇이 백그라운드에서 패널을 동기화하며, 명령이 많으면 잠시 걸립니다.",
    "页面会在当前端口重新打开，机器人配置不会改变。": "현재 포트로 페이지를 다시 엽니다. 봇 구성은 바뀌지 않습니다.",
    "页面版本与运行版本不同，请手动刷新页面；若仍不一致，请手动重启 Harness 或 Desktop。": "페이지 버전과 실행 중인 버전이 다릅니다. 페이지를 직접 새로 고치고, 그래도 다르면 Harness나 Desktop을 직접 다시 시작해 주세요.",
