    "busy": "저장하는 중…",
    "cancel": "취소",
    "chatImageLimit": "대화 이미지 개수 제한",
    "chatImageLimitHint": "대화할 때 모델에 보내는 밈 목록의 최대 개수입니다(\"앞의 N개\"는 설정 파일에 먼저 적은 N개이므로, 보내고 싶은 이미지를 앞쪽으로 옮기세요). 이 목록 전체가 메시지마다 붙고 토큰은 개수에 비례해 늘어나므로 목록이 길면 토큰만 낭비합니다. 앞의 N개로 제한하면 모델은 그 안에서만 고릅니다. 0은 제한 없음(전부 보냄)입니다. 기본값은 10입니다. 모든 펫이 함께 쓰는 전역 기본값이며, 펫 팩은 자체 종류 파일에서 이 값을 바꿀 수 있습니다. 대화에만 적용됩니다. 혼잣말은 뽑힌 밈 하나만 함께 보냅니다.",
    "chatImageToggle": "대화 이미지",
    "chatImageToggleHint": "AI가 현재 맥락에 맞는 밈 하나를 밈 목록에서 골라 붙입니다(고르지 않을 수도 있습니다. 이미지 매핑은 설정 최상위의 `memes` 필드에 있습니다). 토큰: 메시지마다 전체 목록이 붙습니다. 현재 약 1.1k자(약 650토큰, 혼잣말 이미지의 약 11배)이며 이미지 수에 따라 늘어납니다. 끄면 아무것도 붙지 않습니다.",
    "chatMemory": "대화 기록 턴 수",
    "chatMemoryHint": "대화 요청마다 함께 보내는 최근 대화 턴 수입니다(1턴은 질문 1개와 답변 1개입니다. 0이면 기록 없이 매번 새로 시작합니다). 대화 기억 자체는 전부 보관합니다. 이 값은 컨텍스트에 얼마나 넣을지만 정합니다. 클수록 더 많이 기억하지만 토큰을 더 씁니다. 모든 펫이 함께 쓰는 전역 기본값이며, 펫 팩은 자체 종류 파일에서 이 값을 바꿀 수 있습니다.",
