    "configMeta": "고급(파일)",
    "configMetaHint": "사용자 설정으로 펫 목록, 애니메이션 풀, 재생 가중치를 덮어쓸 수 있습니다. 바꾼 뒤 새로 고치거나 다시 시작해야 적용됩니다. 브라우저에서는 페이지를 새로 고치고, 데스크톱에서는 펫을 오른쪽 클릭한 뒤 \"설정 다시 불러오기\"를 고릅니다(모든 데스크톱 펫 창을 다시 만듭니다). 기본 설정이 전체 참고 자료입니다.",
    "confineToggle": "던지기를 현재 화면에 가두기",
    "confineToggleHint": "모니터가 여러 대일 때 던진 펫이 놓은 화면 안에서만 튕깁니다(화면 경계가 벽이 되어 옆 모니터로 날아가지 않습니다). 끄면 평소처럼 화면을 넘나듭니다. 데스크톱에만 적용됩니다. 브라우저 오버레이는 원래 뷰포트 안에서만 튕깁니다.",
