    "storageTitle": "제거와 저장 위치",
    "sync": "동기화",
    "syncHint": "\"동기화\"는 내장 기본 설정(주석과 모든 고급 필드 포함)을 사용자 설정 파일에 써서 지금까지 바꾼 내용을 덮어씁니다. 그다음에는 파일을 직접 고칠 수 있습니다. 두 가지를 주의하세요. (1) 파일을 한 번 만들면 명시적인 덮어쓰기 계층이 되므로, 이후 내장 기본값이 바뀌어도 자동으로 적용되지 않습니다(다시 동기화하거나 파일을 지울 때까지). (2) 이 페이지에서 \"저장\"을 누르면 허용 목록을 기준으로 파일을 다시 쓰므로 필드 값은 남지만 주석은 사라집니다.",
    "uninstallCmd": "dsh plugin --profile {profile} remove dsh-pet",
    "uninstallStep1": "1. 먼저 DSH를 종료하세요(데스크톱 펫도 함께 종료됩니다). 펫이 실행 중일 때 이 파일들을 지우지 마세요.",
    "uninstallStep2": "2. 플러그인 본체를 제거합니다(터미널에서 실행하면 프로필 번들 계층에서도 빠집니다):",
    "uninstallStep3": "3. 필요하면 위 위치를 지웁니다. 캐시 폴더는 지워도 문제없습니다. \"플러그인 사용자 데이터\"를 지우면 설정과 대화 기억이 사라집니다(남기려면 main-config.jsonc를 먼저 백업하세요).",
    "uninstallTitle": "제거 방법",
